{"explanation":"The tangent function is defined as tan(x) = sin(x)/cos(x), so it is undefined wherever cos(x) = 0 — at x = ±π/2 and ±3π/2 within [−2π, 2π]. At these x-values the graph has vertical asymptotes: as x approaches one of them, sin(x) is near ±1 while cos(x) shrinks toward 0, so the quotient explodes toward +∞ or −∞ (the sign depends on the side you approach from, since cos changes sign there). That is why the graph splits into separate S-shaped branches between consecutive asymptotes. Use the slider to move x toward an asymptote and watch cos(x) → 0 while tan(x) blows up.","manimCode":"const PI = Math.PI;
const eps = 0.21;

const axes = new Axes({
  xRange: [-2*PI, 2*PI, PI/2],
  yRange: [-5, 5, 1],
  xLength: 12,
  yLength: 6,
  tips: false
});
const axisLabels = axes.getAxisLabels();

const title = new MathTex({ latex: 'y = \\tan(x) = \\dfrac{\\sin(x)}{\\cos(x)}' });
await title.waitForRender();
title.scale(0.85);
title.toCorner(UL);

await scene.play(new FadeIn(axes));
scene.add(axisLabels);
await scene.play(new Write(title));

const branchRanges = [
  [-2*PI, -3*PI/2 - eps],
  [-3*PI/2 + eps, -PI/2 - eps],
  [-PI/2 + eps, PI/2 - eps],
  [PI/2 + eps, 3*PI/2 - eps],
  [3*PI/2 + eps, 2*PI]
];
const branches = branchRanges.map(function(r) {
  return axes.plot(function(x) { return Math.tan(x); }, { color: BLUE, xRange: r, numSamples: 300 });
});
await scene.play(new AnimationGroup(branches.map(function(b) { return new Create(b); })));

const asymXs = [-3*PI/2, -PI/2, PI/2, 3*PI/2];
const asymLines = asymXs.map(function(a) {
  const ln = new Line({ start: axes.c2p(a, -5), end: axes.c2p(a, 5), color: RED });
  ln.setStrokeWidth(2);
  ln.setOpacity(0.7);
  return ln;
});
await scene.play(new AnimationGroup(asymLines.map(function(l) { return new Create(l); })));

const labelInfo = [
  { a: -3*PI/2, latex: 'x=-\\dfrac{3\\pi}{2}', y: -3.2 },
  { a: -PI/2, latex: 'x=-\\dfrac{\\pi}{2}', y: 3.2 },
  { a: PI/2, latex: 'x=\\dfrac{\\pi}{2}', y: 3.2 },
  { a: 3*PI/2, latex: 'x=\\dfrac{3\\pi}{2}', y: -3.2 }
];
const asymLabels = [];
for (const info of labelInfo) {
  const lbl = new MathTex({ latex: info.latex });
  await lbl.waitForRender();
  lbl.scale(0.5);
  lbl.setColor(RED);
  const px = axes.c2p(info.a, 0)[0];
  lbl.moveTo([px, info.y, 0]);
  asymLabels.push(lbl);
}
await scene.play(new AnimationGroup(asymLabels.map(function(l) { return new FadeIn(l); })));

let xVal = 0.5;
function clampTan(x) {
  const t = Math.tan(x);
  return Math.max(-4.9, Math.min(4.9, t));
}

const guide = new Polygon({ vertices: [axes.c2p(xVal, 0), axes.c2p(xVal, clampTan(xVal))], color: YELLOW });
guide.setStrokeWidth(3);
guide.setFillOpacity(0);
guide.addUpdater(function() {
  guide.setVertices([axes.c2p(xVal, 0), axes.c2p(xVal, clampTan(xVal))]);
});

const dot = new Dot({ point: axes.c2p(xVal, clampTan(xVal)), color: YELLOW });
dot.addUpdater(function() {
  dot.moveTo(axes.c2p(xVal, clampTan(xVal)));
});
scene.add(guide, dot);

let readout = null;
function updateReadout() {
  const t = Math.tan(xVal);
  const c = Math.cos(xVal);
  let tStr;
  if (Math.abs(t) > 50) {
    tStr = t > 0 ? '+∞ (blows up!)' : '-∞ (blows up!)';
  } else {
    tStr = t.toFixed(3);
  }
  const s = 'x = ' + xVal.toFixed(2) + '    tan(x) = ' + tStr + '    cos(x) = ' + c.toFixed(3);
  const pos = readout ? readout.getCenter() : [0, -3.55, 0];
  if (readout) { scene.remove(readout); }
  readout = new Text({ text: s, color: WHITE, fontSize: 20 });
  readout.moveTo(pos);
  scene.add(readout);
}
updateReadout();

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'x value', min: -6.28, max: 6.28, value: xVal, step: 0.01, onChange: function(v) {
  xVal = v;
  updateReadout();
}});
controls.addButton({ label: 'Approach x = π/2', onClick: function() {
  xVal = PI/2 - 0.005;
  updateReadout();
}});

await scene.wait(999999);"}

